values
  ('5c2494d0-035f-4b31-b1d3-09a4b3eff2c3', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'New Media Art Histories, Concepts, and Studio Critique', 'This opening unit gives students a shared language for understanding digital art as an artistic, cultural, and technological practice. It connects studio making to histories of video art, net art, systems art, cyberfeminism, tactical media, interactive installation, and contemporary platform culture.', 0),
  ('59c3974f-fc9c-4af7-9c6e-b56455d8f11f', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '5c2494d0-035f-4b31-b1d3-09a4b3eff2c3', 'subtopic'::public.curated_course_node_type, 'Digital and new media art lineages', 'Students learn how digital practice grows from earlier experiments in photography, video, conceptual art, performance, systems aesthetics, and computer graphics.', 0),
  ('5b360352-d422-49a8-b1b9-2a14a9df9c0f', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '59c3974f-fc9c-4af7-9c6e-b56455d8f11f', 'concept'::public.curated_course_node_type, 'Video art and expanded cinema', null, 0),
