  ('83d658c6-493a-4f2b-9f0c-0e2c6f240c11', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '5322a723-2c64-40dc-81e7-73610e07fcbd', 'concept'::public.curated_course_node_type, 'Respectful, evidence-based feedback', null, 3),
  ('9fe36c43-e21f-45fc-81d3-33e2ba50f7e6', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Digital Workflow, File Formats, Color, Resolution, and Archiving', 'This unit builds the durable habits that let artists move work across software, screens, projectors, printers, web platforms, and archives without losing quality or meaning.', 1),
  ('4867e580-d57a-47c5-97f0-8bb404494f52', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '9fe36c43-e21f-45fc-81d3-33e2ba50f7e6', 'subtopic'::public.curated_course_node_type, 'Digital workflow and versioning', 'Students learn to organize projects so experiments remain reversible, inspectable, and shareable.', 0),
  ('ef305c1a-0ce0-4f8c-994a-99fd90deeb36', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4867e580-d57a-47c5-97f0-8bb404494f52', 'concept'::public.curated_course_node_type, 'Folder structures and naming conventions', null, 0),
