  ('38251d44-0299-4345-b03a-8e5cc2c8a3fc', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '9fe36c43-e21f-45fc-81d3-33e2ba50f7e6', 'subtopic'::public.curated_course_node_type, 'Resolution, compression, and formats', 'The gist is knowing what a file is, what it preserves, and what it throws away.', 1),
  ('5b0be1a2-254d-47af-8dd6-1262357c015e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '38251d44-0299-4345-b03a-8e5cc2c8a3fc', 'concept'::public.curated_course_node_type, 'Raster and vector files', null, 0),
