  ('111ee271-5cfc-4bcc-ac3a-91307a5a87fb', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '9fe36c43-e21f-45fc-81d3-33e2ba50f7e6', 'subtopic'::public.curated_course_node_type, 'Color and display management', 'Students develop practical judgment about how color changes across monitors, projectors, print, and mobile devices.', 2),
