  ('694dbf7e-5158-48cd-986a-b3477d032bf5', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '111ee271-5cfc-4bcc-ac3a-91307a5a87fb', 'concept'::public.curated_course_node_type, 'Bit depth and dynamic range', null, 2),
  ('c1705345-3718-41ff-9a14-ba24cdf6d006', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '111ee271-5cfc-4bcc-ac3a-91307a5a87fb', 'concept'::public.curated_course_node_type, 'Accessibility and contrast', null, 3),
  ('e2db2161-c493-4f34-918b-943e250c84d2', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Digital Imaging, Compositing, and Photographic Manipulation', 'This unit treats the digital image as a constructed object. Students learn how to manipulate, composite, repair, distort, and question photographic images while staying alert to ethics and visual evidence.', 2),
  ('dd1a4839-89bc-4816-be8b-7a98c8765d62', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'e2db2161-c493-4f34-918b-943e250c84d2', 'subtopic'::public.curated_course_node_type, 'Layer-based image construction', 'Students learn how complex images are built through non-destructive layering, masks, selections, and adjustment systems.', 0),
  ('827b51eb-1ed5-4c58-a458-38b4a60b05b2', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'dd1a4839-89bc-4816-be8b-7a98c8765d62', 'concept'::public.curated_course_node_type, 'Selections and masking', null, 0),
