  ('980e8657-e361-4bd4-954a-28dcdfdd9b52', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Digital Painting, Drawing, Collage, and Hybrid Image-Making', 'Digital painting is not just traditional drawing on a screen. This unit explores brushes, tablets, collage systems, procedural textures, and hybrid workflows that combine analog and digital marks.', 3),
  ('32c4734d-9f97-475d-b7cf-bee49e6de22a', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '980e8657-e361-4bd4-954a-28dcdfdd9b52', 'subtopic'::public.curated_course_node_type, 'Digital drawing tools and mark-making', 'Students learn how pressure, texture, brushes, layers, and stylus control shape expressive visual language.', 0),
