  ('5c177da7-362c-4253-984d-336c6eed7878', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '8f58f0fe-4696-408f-9f99-caa4b901625f', 'concept'::public.curated_course_node_type, 'Critique of consistency and surprise', null, 3),
  ('a50519db-6a93-4686-b1a2-6b36a1e5f8eb', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Time-Based Media: Video, Editing, Motion, and Animation', 'Time-based media teaches students to compose with duration, rhythm, sequence, and change. This unit bridges video art, motion graphics, animation, and experimental editing.', 4),
