  ('17f91233-ac58-4cc1-b8f9-5c1db0780109', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Sound Art, Audio Editing, Sampling, and Spatial Listening', 'Sound expands digital art beyond the visual. Students learn to listen, record, edit, spatialize, and integrate audio as material, environment, signal, and interface.', 5),
  ('0f685a1a-54cb-4a1c-bb31-b28a7d1ba47c', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '17f91233-ac58-4cc1-b8f9-5c1db0780109', 'subtopic'::public.curated_course_node_type, 'Listening and field recording', 'Students learn that sound work begins with attention: what is heard, where it is heard, and how recording transforms it.', 0),
