  ('f9d1927d-b5f1-44a0-9f95-b116480ccf72', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '21104ac8-7a9e-452a-ba63-f0c4eb5d75c5', 'concept'::public.curated_course_node_type, 'Speakers and spatial placement', null, 0),
