  ('79523e38-6197-48be-bf16-ceb13811ebca', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Creative Coding Foundations: Processing, p5.js, and Generative Systems', 'Creative coding lets students design processes rather than only fixed artifacts. This unit introduces programming as a studio material for drawing, animation, chance, interaction, and generative form.', 6),
