  ('245c18d1-afdd-43c6-984b-0446fbf78c53', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4689ddf3-ade2-4a18-bbc2-4b774043a388', 'concept'::public.curated_course_node_type, 'Variables, conditionals, loops, and functions', null, 0),
