  ('36218f6a-3bcd-4521-88ab-f9cc6f157a39', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4689ddf3-ade2-4a18-bbc2-4b774043a388', 'concept'::public.curated_course_node_type, 'Color, shape, and typography', null, 2),
  ('bb47360a-a1ae-42e6-8f1f-8099f22b3119', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4689ddf3-ade2-4a18-bbc2-4b774043a388', 'concept'::public.curated_course_node_type, 'Debugging and code reading', null, 3),
