  ('457cc981-ff32-41e4-8509-423c2d67acf6', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Web-Based, Networked, and Browser-Based Art', 'The web is both a medium and a public site of distribution. This unit treats HTML, CSS, JavaScript, networks, browsers, and platforms as artistic materials.', 7),
