  ('55b8a3a9-e952-44e6-b48c-364b008de92e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'b6c1b3f2-b4a6-4add-871b-3665006b6dd9', 'concept'::public.curated_course_node_type, 'Affordances and feedback', null, 0),
