  ('f8406ff2-f9fe-4fab-816f-08f7a178374d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'b5b8a1c9-574f-4ea1-96d7-28e98113c8b3', 'concept'::public.curated_course_node_type, 'Arduino boards and circuits', null, 0),
