  ('8d67ce4e-79da-418f-aedf-5446052090de', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'b5b8a1c9-574f-4ea1-96d7-28e98113c8b3', 'concept'::public.curated_course_node_type, 'LEDs, motors, and displays', null, 2),
  ('e307a32d-1542-44b9-85aa-746b9ad8cc86', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'b5b8a1c9-574f-4ea1-96d7-28e98113c8b3', 'concept'::public.curated_course_node_type, 'Serial communication', null, 3),
  ('49c1b226-2a5d-4cc2-8df8-83d1950bc1a8', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'dc33ff42-1dfe-46ae-9b53-cbc38a6ee2e7', 'subtopic'::public.curated_course_node_type, 'Participation, consent, and care', 'Students consider how interactive systems affect bodies, privacy, agency, and access.', 2),
  ('3a93e904-62a5-47cc-bbd0-3a57465a4ad7', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '49c1b226-2a5d-4cc2-8df8-83d1950bc1a8', 'concept'::public.curated_course_node_type, 'Data capture and consent', null, 0),
  ('e43bb7c8-7aca-4c23-af89-d799e6860603', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '49c1b226-2a5d-4cc2-8df8-83d1950bc1a8', 'concept'::public.curated_course_node_type, 'Accessible interaction', null, 1),
