  ('eb2898ff-9607-4001-9c6d-444c0870e774', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '49c1b226-2a5d-4cc2-8df8-83d1950bc1a8', 'concept'::public.curated_course_node_type, 'Maintenance during exhibition', null, 3),
  ('455e08a5-2231-4baa-b657-34965110cf64', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, '3D Modeling, Rendering, Simulation, and Virtual Space', 'Three-dimensional digital work gives students tools for sculpture, environment, image-making, animation, fabrication, and immersive worlds. This unit teaches 3D thinking without reducing it to software buttons.', 9),
  ('f0cc49c9-a314-4735-a4a1-c3fab3847d7c', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '455e08a5-2231-4baa-b657-34965110cf64', 'subtopic'::public.curated_course_node_type, 'Modeling and scene construction', 'Students learn how objects, surfaces, scale, and spatial relationships are built in digital environments.', 0),
  ('5feb43b0-07f4-47f3-9b82-c6604677cc57', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f0cc49c9-a314-4735-a4a1-c3fab3847d7c', 'concept'::public.curated_course_node_type, 'Mesh, curve, and primitive modeling', null, 0),
  ('c7e96f04-eb3a-45d2-a180-4ded815d0938', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f0cc49c9-a314-4735-a4a1-c3fab3847d7c', 'concept'::public.curated_course_node_type, 'Topology and normals', null, 1),
  ('1ddf20d0-de4b-44ea-a9a8-c779ae43d19e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f0cc49c9-a314-4735-a4a1-c3fab3847d7c', 'concept'::public.curated_course_node_type, 'Scale and units', null, 2),
