  ('5ec427f5-6d1c-40ef-b5f5-b41b6dfd233e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'b9478fb6-6677-4824-83c8-841ea52fe3b6', 'concept'::public.curated_course_node_type, 'Still and animated renders', null, 3),
  ('4d3bde48-0953-420a-9b19-75627e119258', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '455e08a5-2231-4baa-b657-34965110cf64', 'subtopic'::public.curated_course_node_type, 'Simulation and virtual sculpture', 'The unit introduces systems that behave over time, from cloth and particles to procedural environments.', 2),
  ('26724917-365a-4351-af72-497b5359ba07', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4d3bde48-0953-420a-9b19-75627e119258', 'concept'::public.curated_course_node_type, 'Physics simulation', null, 0),
  ('a039dc9a-72dd-4c99-8ceb-82f4ffd15f7a', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4d3bde48-0953-420a-9b19-75627e119258', 'concept'::public.curated_course_node_type, 'Particles and fields', null, 1),
  ('8e14f434-4cb1-4a26-b934-0f7d9e51f0a1', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '4d3bde48-0953-420a-9b19-75627e119258', 'concept'::public.curated_course_node_type, 'Procedural landscapes', null, 2),
