insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('67e8e0ca-2400-48b0-80c5-a0cc2dd86f6c', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Game Engines, Real-Time Environments, AR/VR/XR, and Immersive Media', 'Real-time media changes the artwork from a fixed output into a responsive world. Students learn how game engines and immersive platforms support spatial storytelling, simulation, performance, and installation.', 10),
  ('391d860e-a4f1-4cac-89a4-b614f815272b', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '67e8e0ca-2400-48b0-80c5-a0cc2dd86f6c', 'subtopic'::public.curated_course_node_type, 'Game engine fundamentals', 'Students learn core concepts that transfer across Unity, Unreal, and similar real-time tools.', 0),
  ('f2219d06-dfbc-4758-9645-c5ff742c046c', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '391d860e-a4f1-4cac-89a4-b614f815272b', 'concept'::public.curated_course_node_type, 'Scenes, assets, and prefabs', null, 0),
  ('1f1e8ecf-9109-4c98-97c9-e4d662189c17', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '391d860e-a4f1-4cac-89a4-b614f815272b', 'concept'::public.curated_course_node_type, 'Cameras, lights, and materials', null, 1),
  ('7237bf1b-35f0-4116-bc1c-6dc18875d081', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '391d860e-a4f1-4cac-89a4-b614f815272b', 'concept'::public.curated_course_node_type, 'Physics and collision', null, 2),
  ('81756c53-83d8-4b4a-af39-7616e069b81d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '391d860e-a4f1-4cac-89a4-b614f815272b', 'concept'::public.curated_course_node_type, 'Build settings and deployment', null, 3),
