  ('f3293314-f818-4204-af02-f107f6a38638', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f816e4c7-edc4-4458-85ce-d439e1261a4f', 'concept'::public.curated_course_node_type, 'Level and environment design', null, 0),
  ('fa48154c-d4a2-4738-ac4c-b6d9a5557e5d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f816e4c7-edc4-4458-85ce-d439e1261a4f', 'concept'::public.curated_course_node_type, 'Navigation and player perspective', null, 1),
  ('e2505560-d88b-4bf2-a893-d91f8c193c5a', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f816e4c7-edc4-4458-85ce-d439e1261a4f', 'concept'::public.curated_course_node_type, 'Sound and spatial cues', null, 2),
  ('40c0f474-d6bc-4e5d-9074-21b0f4ea9942', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'f816e4c7-edc4-4458-85ce-d439e1261a4f', 'concept'::public.curated_course_node_type, 'Rules, goals, and ambiguity', null, 3),
