  ('9d49ef7b-2a81-490f-ac1b-a57a185e2543', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'df61fa2f-e8bf-49ae-bddd-954a457288da', 'concept'::public.curated_course_node_type, 'Headsets and mobile AR', null, 0),
  ('90f3c7c9-e93c-4080-a0a1-ba1754da496e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'df61fa2f-e8bf-49ae-bddd-954a457288da', 'concept'::public.curated_course_node_type, 'Motion comfort and embodiment', null, 1),
  ('9d3a9e37-dd4a-48df-8e24-403520878ee2', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'df61fa2f-e8bf-49ae-bddd-954a457288da', 'concept'::public.curated_course_node_type, 'Spatial UI', null, 2),
  ('c5568874-8b91-493e-a598-ed4e73eab51b', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', 'df61fa2f-e8bf-49ae-bddd-954a457288da', 'concept'::public.curated_course_node_type, 'Safety, surveillance, and presence', null, 3),
  ('7d6a4c81-4cc0-4406-ae03-754b5aa89163', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Data, Visualization, Machine Vision, AI, and Algorithmic Critique', 'Artists increasingly work with datasets, models, sensors, and automated systems. This unit teaches students to use algorithmic tools while questioning what they measure, omit, classify, and amplify.', 11),
  ('115e3476-2d00-40cf-8c63-21484fb5687b', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '7d6a4c81-4cc0-4406-ae03-754b5aa89163', 'subtopic'::public.curated_course_node_type, 'Data as artistic material', 'Students learn to gather, clean, interpret, and transform data into form without pretending data is neutral.', 0),
  ('2685cdf4-eca3-42f3-b185-7ebf4370193e', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '115e3476-2d00-40cf-8c63-21484fb5687b', 'concept'::public.curated_course_node_type, 'Dataset sources and documentation', null, 0),
  ('9924efc4-b54a-42d6-8c89-bcc0a12042ee', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '115e3476-2d00-40cf-8c63-21484fb5687b', 'concept'::public.curated_course_node_type, 'Cleaning and uncertainty', null, 1),
  ('2e703ec0-9730-45f7-8915-97cfd7e3559d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '115e3476-2d00-40cf-8c63-21484fb5687b', 'concept'::public.curated_course_node_type, 'Mappings from data to image, sound, or motion', null, 2),
  ('ef79ae23-e5f5-49df-bd37-90fe93d96f4d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '115e3476-2d00-40cf-8c63-21484fb5687b', 'concept'::public.curated_course_node_type, 'Data feminism and situated knowledge', null, 3),
  ('28e1bb0c-e49c-4657-91db-a343775b2273', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '7d6a4c81-4cc0-4406-ae03-754b5aa89163', 'subtopic'::public.curated_course_node_type, 'Machine vision and AI systems', 'Students explore computer vision and AI-assisted making as creative tools and cultural objects.', 1),
  ('b584e9c4-9d6d-405e-8c2b-a3d4ea8e9bc4', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '28e1bb0c-e49c-4657-91db-a343775b2273', 'concept'::public.curated_course_node_type, 'Image classification and detection', null, 0),
  ('e909ffef-8f98-425e-890c-9265ddc3f3a7', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '28e1bb0c-e49c-4657-91db-a343775b2273', 'concept'::public.curated_course_node_type, 'Pose and face tracking', null, 1),
  ('f57acfc8-ff17-460b-83b4-e8aa41b419e5', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '28e1bb0c-e49c-4657-91db-a343775b2273', 'concept'::public.curated_course_node_type, 'Text-to-image and generative tools', null, 2),
  ('9d34ae87-2980-417f-a492-70daeb916513', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '28e1bb0c-e49c-4657-91db-a343775b2273', 'concept'::public.curated_course_node_type, 'Model limits, bias, and hallucination', null, 3),
  ('93035d91-2d3e-465b-9e8d-7c3f61abc235', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '7d6a4c81-4cc0-4406-ae03-754b5aa89163', 'subtopic'::public.curated_course_node_type, 'Algorithmic critique', 'The goal is to understand computation as power: classification, prediction, sorting, and automation.', 2),
  ('7e4e362c-6416-4797-ba0c-6def75608e04', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '93035d91-2d3e-465b-9e8d-7c3f61abc235', 'concept'::public.curated_course_node_type, 'Bias and representational harm', null, 0),
  ('112aa7ad-cf77-491b-9211-35b14f77d22d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '93035d91-2d3e-465b-9e8d-7c3f61abc235', 'concept'::public.curated_course_node_type, 'Training data and consent', null, 1),
  ('ad141116-29a9-4ec0-8541-e8c21fe188ea', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '93035d91-2d3e-465b-9e8d-7c3f61abc235', 'concept'::public.curated_course_node_type, 'Automation and labor', null, 2),
  ('6aafc408-67f6-48e7-a50b-cf55db182b64', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '93035d91-2d3e-465b-9e8d-7c3f61abc235', 'concept'::public.curated_course_node_type, 'Transparency, refusal, and counter-design', null, 3),
  ('c6d1449a-e2af-464f-93c0-6ac35133800f', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Installation, Projection Mapping, Exhibition Design, and Technical Production', 'New media works often become real only in space. This unit teaches students to design for walls, rooms, bodies, light, sound, cables, projectors, screens, and gallery operations.', 12),
