  ('99f8cc7d-6b03-4d3d-a9f2-e9a4bf0703a6', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '91c1ed5c-5c05-4da3-a974-02f4c12b2358', 'concept'::public.curated_course_node_type, 'Floor plans and sightlines', null, 0),
