  ('e3baadba-1ad4-46d8-9716-bb0f79ac9a3d', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '91c1ed5c-5c05-4da3-a974-02f4c12b2358', 'concept'::public.curated_course_node_type, 'Audience flow and dwell time', null, 2),
