  ('566dccf5-0869-4601-bdda-e47167976416', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '1c422c48-f2f3-420e-92c4-6c750919f04c', 'concept'::public.curated_course_node_type, 'Risk assessment and backups', null, 3),
  ('5a4b680b-74d4-4375-83cf-32424bbf6770', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', null, 'topic'::public.curated_course_node_type, 'Preservation, Documentation, Accessibility, Copyright, and Platform Ethics', 'Digital artworks are fragile because platforms, formats, hardware, and social contexts change. This unit teaches students to document, license, preserve, and present work responsibly.', 13),
  ('485c79f9-b53c-4d00-a32a-67e586a586d4', 'c3d4e5f6-7a8b-4c55-8f45-5a6b7c8d9e15', '5a4b680b-74d4-4375-83cf-32424bbf6770', 'subtopic'::public.curated_course_node_type, 'Documentation and preservation strategies', 'Students learn to create records that help future viewers, curators, collaborators, and the artist''s own archive.', 0),
